(function(){
  "use strict";

  // Backend used only for the working link-share flow (dynamic OG image preview).
  // Leave empty ('') to disable link-preview sharing and rely on native file share / download only.
  const BACKEND_URL = window.location.host.includes('localhost') ? "http://localhost:3000" : "";

  const ringImg = new Image();
  let ringImgReady = false;
  ringImg.onload = ()=>{ ringImgReady = true; if(mode==='pfp') drawFinal(); };
  ringImg.src = "data:image/webp;base64,";

  const badgeWatermarkImg = new Image();
  let badgeWatermarkReady = false;
  badgeWatermarkImg.onload = ()=>{ badgeWatermarkReady = true; if(mode==='badge') drawFinal(); };
  badgeWatermarkImg.src = "data:image/webp;base64,";

  const frontCardImg = new Image();
  let frontCardReady = false;
  frontCardImg.onload = ()=>{ frontCardReady = true; if(mode==='badge') drawFinal(); };
  frontCardImg.src = "data:image/webp;base64,";

  const backCardImg = new Image();
  let backCardReady = false;
  backCardImg.onload = ()=>{ backCardReady = true; if(mode==='badge') drawFinal(); };
  backCardImg.src = "data:image/webp;base64,";

  let mode = 'pfp';
  const state = {
    pfp:   { img:null, offX:0, offY:0, zoom:1 },
    badge: { img:null, offX:0, offY:0, zoom:1 }
  };
  let dragging=false, dragStart={x:0,y:0}, dragOrigin={x:0,y:0};

  // Unique code for badge (changes on each render)
  let uniqueCode = generateUniqueCode();

  function generateUniqueCode(){
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for(let i=0; i<4; i++){
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return 'HHG26-' + code;
  }

  const $ = (id)=>document.getElementById(id);
  const cropCanvas = $('cropCanvas');
  const cropCtx = cropCanvas.getContext('2d');
  const finalCanvas = $('finalCanvas');
  const finalCtx = finalCanvas.getContext('2d');
  const stage = $('stage');
  const stageWrap = $('stageWrap');
  const dropzone = $('dropzone');
  const fileInput = $('fileInput');
  const zoomSlider = $('zoomSlider');
  const uploadStatus = $('uploadStatus');
  const badgeFields = $('badgeFields');
  const outStepNum = $('outStepNum');

  document.querySelectorAll('.tab-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      mode = btn.dataset.tab;
      badgeFields.style.display = mode==='badge' ? 'block' : 'none';
      outStepNum.textContent = mode==='badge' ? '3' : '2';
      stage.classList.toggle('rect', mode==='badge');
      syncCropCanvasSize();
      // Regenerate unique code when switching to badge
      if(mode==='badge') uniqueCode = generateUniqueCode();
      drawCrop(); drawFinal();
    });
  });

  function syncCropCanvasSize(){
    if(mode==='badge'){ cropCanvas.width=640; cropCanvas.height=480; }
    else { cropCanvas.width=640; cropCanvas.height=640; }
  }

  dropzone.addEventListener('click', ()=>fileInput.click());
  dropzone.addEventListener('dragover', e=>{ e.preventDefault(); dropzone.classList.add('drag'); });
  dropzone.addEventListener('dragleave', ()=>dropzone.classList.remove('drag'));
  dropzone.addEventListener('drop', e=>{
    e.preventDefault(); dropzone.classList.remove('drag');
    if(e.dataTransfer.files && e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);
  });
  fileInput.addEventListener('change', e=>{
    if(e.target.files && e.target.files[0]) handleFile(e.target.files[0]);
  });

  function showStatus(msg){ uploadStatus.textContent = msg; uploadStatus.className = 'status show'; }
  function hideStatus(){ uploadStatus.className = 'status'; }

  function handleFile(file){
    hideStatus();
    const isHeic = /\.hei[cf]$/i.test(file.name) || /image\/hei[cf]/i.test(file.type);
    const reader = new FileReader();
    reader.onload = function(ev){
      const img = new Image();
      img.onload = function(){
        if(img.naturalWidth < 20){ onDecodeFail(isHeic); return; }
        ['pfp','badge'].forEach(k=>{ state[k].img = img; state[k].offX=0; state[k].offY=0; state[k].zoom=1; });
        zoomSlider.value = 100;
        stageWrap.classList.remove('hidden');
        stage.classList.toggle('rect', mode==='badge');
        syncCropCanvasSize();
        // Regenerate unique code on new upload for badge
        if(mode==='badge') uniqueCode = generateUniqueCode();
        drawCrop(); drawFinal();
      };
      img.onerror = function(){ onDecodeFail(isHeic); };
      img.src = ev.target.result;
    };
    reader.onerror = function(){ showStatus('Could not read that file — try a different photo.'); };
    reader.readAsDataURL(file);
  }

  function onDecodeFail(isHeic){
    if(isHeic){
      showStatus("This HEIC photo couldn't be previewed on this browser. On iPhone: Settings → Camera → Formats → \"Most Compatible\" saves new photos as JPG, or choose \"Convert to JPG\" when picking the file.");
    } else {
      showStatus("Couldn't open that image — try a JPG or PNG.");
    }
  }

  function pointerPos(e){
    const rect = cropCanvas.getBoundingClientRect();
    const cx = (e.touches ? e.touches[0].clientX : e.clientX);
    const cy = (e.touches ? e.touches[0].clientY : e.clientY);
    return { x: (cx-rect.left) * (cropCanvas.width/rect.width), y: (cy-rect.top) * (cropCanvas.height/rect.height) };
  }
  stage.addEventListener('pointerdown', e=>{
    if(!state[mode].img) return;
    dragging = true; stage.setPointerCapture(e.pointerId);
    const p = pointerPos(e);
    dragStart = p; dragOrigin = { x: state[mode].offX, y: state[mode].offY };
  });
  stage.addEventListener('pointermove', e=>{
    if(!dragging) return;
    const p = pointerPos(e);
    state[mode].offX = dragOrigin.x + (p.x-dragStart.x);
    state[mode].offY = dragOrigin.y + (p.y-dragStart.y);
    clampOffsets(mode, cropCanvas.width, cropCanvas.height);
    drawCrop(); drawFinal();
  });
  ['pointerup','pointerleave','pointercancel'].forEach(evt=>{
    stage.addEventListener(evt, ()=>{ dragging=false; });
  });

  zoomSlider.addEventListener('input', ()=>{
    state[mode].zoom = zoomSlider.value/100;
    clampOffsets(mode, cropCanvas.width, cropCanvas.height);
    drawCrop(); drawFinal();
  });

  function imageDrawRect(s, tw, th){
    const img = s.img;
    const base = Math.max(tw/img.naturalWidth, th/img.naturalHeight);
    const eff = base * s.zoom;
    const dw = img.naturalWidth*eff, dh = img.naturalHeight*eff;
    const cx = tw/2 + s.offX, cy = th/2 + s.offY;
    return { x: cx-dw/2, y: cy-dh/2, w: dw, h: dh };
  }
  function clampOffsets(k, tw, th){
    const s = state[k];
    if(!s.img) return;
    const r = imageDrawRect({img:s.img, offX:0, offY:0, zoom:s.zoom}, tw, th);
    const maxX = Math.max(0, (r.w-tw)/2);
    const maxY = Math.max(0, (r.h-th)/2);
    s.offX = Math.max(-maxX, Math.min(maxX, s.offX));
    s.offY = Math.max(-maxY, Math.min(maxY, s.offY));
  }

  function drawCrop(){
    const s = state[mode];
    cropCtx.clearRect(0,0,cropCanvas.width,cropCanvas.height);
    cropCtx.fillStyle = '#000';
    cropCtx.fillRect(0,0,cropCanvas.width,cropCanvas.height);
    if(!s.img) return;
    const r = imageDrawRect(s, cropCanvas.width, cropCanvas.height);
    cropCtx.drawImage(s.img, r.x, r.y, r.w, r.h);
    if(mode==='pfp'){
      cropCtx.save();
      cropCtx.globalCompositeOperation='destination-in';
      cropCtx.beginPath();
      cropCtx.arc(cropCanvas.width/2, cropCanvas.height/2, cropCanvas.width/2, 0, Math.PI*2);
      cropCtx.fill();
      cropCtx.restore();
      cropCtx.save();
      cropCtx.globalCompositeOperation='destination-over';
      cropCtx.fillStyle='#000';
      cropCtx.fillRect(0,0,cropCanvas.width,cropCanvas.height);
      cropCtx.restore();
    }
  }

  function drawArcText(ctx, text, cx, cy, radius, startDeg, endDeg, font, color){
    // Not used anymore – we keep for reference but not called.
  }

  function roundRect(ctx,x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y);
    ctx.arcTo(x+w,y,x+w,y+h,r);
    ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r);
    ctx.arcTo(x,y,x+w,y,r);
    ctx.closePath();
  }

  /* Draw a large semi‑transparent watermark */
  function drawWatermark(ctx, text, w, h, angle, color, size){
    ctx.save();
    ctx.translate(w/2, h/2);
    ctx.rotate(angle);
    ctx.font = `700 ${size}px 'Bodoni Moda', serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, 0, 0);
    ctx.restore();
  }

  /* PFP render — user's photo sits inside the transparent hole of the ring artwork */
  function renderPFP(){
    const N = 1080;
    finalCanvas.width = N; finalCanvas.height = N;
    const ctx = finalCtx;
    ctx.clearRect(0,0,N,N);
    ctx.fillStyle = '#053E24'; ctx.fillRect(0,0,N,N);

    // Photo circle: matches the ring artwork's inner hole (~0.66 of canvas, centered slightly above middle)
    const holeR = N*0.348;
    const cx = N/2, cy = N/2 - N*0.020;
    ctx.save();
    ctx.beginPath(); ctx.arc(cx,cy,holeR,0,Math.PI*2); ctx.clip();
    const s = state.pfp;
    if(s.img){
      const r = imageDrawRect(s, holeR*2, holeR*2);
      ctx.drawImage(s.img, cx-holeR + r.x, cy-holeR + r.y, r.w, r.h);
    } else {
      ctx.fillStyle = '#036736';
      ctx.fillRect(cx-holeR, cy-holeR, holeR*2, holeR*2);
      ctx.fillStyle = 'rgba(247,243,233,0.4)';
      ctx.font = `600 26px 'IBM Plex Mono'`; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('upload a photo', cx, cy);
    }
    ctx.restore();

    // Ring artwork overlay (transparent center reveals the photo above)
    if(ringImgReady){
      ctx.drawImage(ringImg, 0, 0, N, N);
    }
  }

  /* Builder Badge render — front card (photo, details, barcode) + back card (pass info, QR) side by side, one combined image */
  function renderBadge(){
    const CW = 600, CH = 900, GAP = 60, PAD = 40;
    const W = PAD*2 + CW*2 + GAP, H = PAD*2 + CH;
    finalCanvas.width = W; finalCanvas.height = H;
    const ctx = finalCtx;
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle = '#012417'; ctx.fillRect(0,0,W,H);

    drawFrontCard(ctx, PAD, PAD, CW, CH);
    drawBackCard(ctx, PAD+CW+GAP, PAD, CW, CH);
  }

  function drawFlower(ctx, cx, cy, r, color){
    ctx.save();
    ctx.translate(cx,cy);
    ctx.fillStyle = color;
    for(let i=0;i<5;i++){
      ctx.save();
      ctx.rotate(i * (Math.PI*2/5));
      ctx.beginPath();
      ctx.ellipse(0, -r*0.6, r*0.42, r*0.62, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.restore();
    }
    ctx.fillStyle = '#FEE101';
    ctx.beginPath(); ctx.arc(0,0,r*0.28,0,Math.PI*2); ctx.fill();
    ctx.restore();
  }

  function drawPalmSilhouette(ctx, x, y, scale, flip){
    ctx.save();
    ctx.translate(x,y);
    ctx.scale(flip?-scale:scale, scale);
    ctx.strokeStyle = 'rgba(247,243,233,0.55)';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(0,0); ctx.quadraticCurveTo(-10,-60,-4,-120); ctx.stroke();
    for(let i=0;i<5;i++){
      const ang = -0.3 + i*0.35;
      ctx.beginPath();
      ctx.moveTo(-4,-120);
      ctx.quadraticCurveTo(-4+Math.cos(ang)*30, -120+Math.sin(ang)*10-20, -4+Math.cos(ang)*55, -120+Math.sin(ang)*20-10);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawIconGlyph(ctx, glyph, cx, cy, R){
    ctx.save();
    ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2);
    ctx.strokeStyle = '#FEE101'; ctx.lineWidth = 2.5; ctx.stroke();
    ctx.font = `${Math.round(R*1.0)}px sans-serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(glyph, cx, cy+1);
    ctx.restore();
  }

  function renderQRCanvas(value, size, fg, bg){
    const c = document.createElement('canvas');
    c.width = size; c.height = size;
    if(typeof QRious !== 'undefined'){
      new QRious({ element:c, value, size, foreground:fg, background:bg, level:'M' });
    } else {
      const ctx2 = c.getContext('2d');
      ctx2.fillStyle = bg; ctx2.fillRect(0,0,size,size);
      ctx2.fillStyle = fg; ctx2.font='11px monospace'; ctx2.textAlign='center';
      ctx2.fillText('QR unavailable', size/2, size/2);
    }
    return c;
  }

  function renderBarcodeCanvas(value, width, height){
    const c = document.createElement('canvas');
    if(typeof JsBarcode !== 'undefined'){
      try{
        JsBarcode(c, value, {
          format:'CODE128', width:2, height: height*0.7, displayValue:true,
          font:'IBM Plex Mono', fontSize:13, textMargin:2, margin:4,
          background:'#F7F3E9', lineColor:'#012417'
        });
      }catch(e){ c.width=width; c.height=height; }
    } else {
      c.width = width; c.height = height;
      const ctx2 = c.getContext('2d');
      ctx2.fillStyle = '#F7F3E9'; ctx2.fillRect(0,0,width,height);
      ctx2.fillStyle = '#012417'; ctx2.font='11px monospace'; ctx2.textAlign='center';
      ctx2.fillText('barcode unavailable', width/2, height/2);
    }
    return c;
  }

  /* ---------------- FRONT CARD (template image + live overlays) ---------------- */
  function drawFrontCard(ctx, x, y, w, h){
    ctx.save();
    ctx.translate(x,y);

    roundRect(ctx,0,0,w,h,22); ctx.save(); ctx.clip();

    // Template artwork (measured against its native 1024x1536 canvas)
    if(frontCardReady){
      ctx.drawImage(frontCardImg, 0, 0, w, h);
    } else {
      ctx.fillStyle = '#053E24'; ctx.fillRect(0,0,w,h);
    }

    const sx = w/1024; // template's native width the coordinates below were measured against

    // Photo box — accurate, undistorted cover-crop. Slightly enlarged past the
    // measured dashed-border box so the photo fully covers it with no gap/outline peeking out.
    const boxX = 51*sx, boxY = 671*sx, boxW = 367*sx, boxH = 543*sx;
    ctx.save();
    roundRect(ctx, boxX, boxY, boxW, boxH, 8*sx); ctx.clip();
    const s = state.badge;
    if(s.img){
      const r = imageDrawRect(s, boxW, boxH);
      ctx.drawImage(s.img, boxX+r.x, boxY+r.y, r.w, r.h);
    }
    ctx.restore();

    // Fields (values only — labels/underlines are already printed in the template; no baked-in
    // placeholder text on this template, so no cover-rects needed)
    // Fields (values only — labels/underlines are already printed in the template)
    const fx = 474*sx;
    ctx.textAlign='left';
    const name = ($('nameInput').value || 'Your Name').slice(0,22);
    const role = ($('roleInput').value || 'Builder').slice(0,24);
    const company = ($('companyInput').value || 'HH Goa 2026').slice(0,30);
    const titleVal = ($('titleInput').value || 'Full-Stack Engineer').slice(0,34);

    // 1. Name
    ctx.font = `700 ${32*sx}px 'Bodoni Moda'`; ctx.fillStyle='#012417';
    ctx.fillText(name, fx, 730*sx);

    // 2. Role / Stack
    ctx.font = `700 ${26*sx}px 'Bodoni Moda'`; ctx.fillStyle='#FF0080';
    ctx.fillText(role.toUpperCase(), fx, 825*sx);

    // 3. Team / Company
    ctx.font = `700 ${24*sx}px 'Bodoni Moda'`; ctx.fillStyle='#012417';
    ctx.fillText(company, fx, 915*sx);

    // 4. Builder Title
    ctx.font = `600 ${22*sx}px 'IBM Plex Mono'`; ctx.fillStyle='#036736';
    ctx.fillText('⚡ ' + titleVal, fx, 1005*sx);

    // 5. Code
    ctx.font = `700 ${26*sx}px 'IBM Plex Mono'`; ctx.fillStyle='#FF0080';
    ctx.fillText(uniqueCode, fx, 1095*sx);

    // 6. Barcode
    const bcX = 474*sx, bcY = 1145*sx, bcW = 484*sx, bcH = 80*sx;
    const bcCanvas = renderBarcodeCanvas(uniqueCode, Math.round(bcW), Math.round(bcH));
    ctx.drawImage(bcCanvas, bcX, bcY, bcW, bcH);

    ctx.restore(); // end clip

    ctx.strokeStyle = 'rgba(254,225,1,0.35)'; ctx.lineWidth = 2;
    roundRect(ctx,1,1,w-2,h-2,22); ctx.stroke();

    ctx.restore();
  }

  /* ---------------- BACK CARD (template image + QR overlay) ---------------- */
  function drawBackCard(ctx, x, y, w, h){
    ctx.save();
    ctx.translate(x,y);

    roundRect(ctx,0,0,w,h,22); ctx.save(); ctx.clip();

    if(backCardReady){
      ctx.drawImage(backCardImg, 0, 0, w, h);
    } else {
      ctx.fillStyle = '#053E24'; ctx.fillRect(0,0,w,h);
    }

    const sx = w/1023; // back template's native width

    // QR code inside the dashed cream box
    const qrX = 143*sx, qrY = 1190*sx, qrW = 187*sx, qrH = 198*sx;
    const qrSize = Math.round(Math.min(qrW, qrH) - 14*sx);
    const qrCanvas = renderQRCanvas('https://hhgoa.com/', qrSize, '#036736', '#F7F3E9');
    ctx.drawImage(qrCanvas, qrX + (qrW-qrSize)/2, qrY + (qrH-qrSize)/2, qrSize, qrSize);

    ctx.restore(); // end clip

    ctx.strokeStyle = 'rgba(254,225,1,0.35)'; ctx.lineWidth = 2;
    roundRect(ctx,1,1,w-2,h-2,22); ctx.stroke();

    ctx.restore();
  }

  function wrapStrokeText(ctx, text, x, y, maxWidth, lineHeight){
    const words = text.split(' ');
    let line = '', ly = y, lines=[];
    for(let i=0;i<words.length;i++){
      const test = line + words[i] + ' ';
      if(ctx.measureText(test).width > maxWidth && line){ lines.push(line); line = words[i]+' '; }
      else line = test;
    }
    lines.push(line);
    lines.slice(0,2).forEach((l,i)=> ctx.strokeText(l.trim(), x, ly+i*lineHeight));
  }

  function wrapFillText(ctx, text, x, y, maxWidth, lineHeight){
    const words = text.split(' ');
    let line = '', ly = y, lines=[];
    for(let i=0;i<words.length;i++){
      const test = line + words[i] + ' ';
      if(ctx.measureText(test).width > maxWidth && line){ lines.push(line); line = words[i]+' '; }
      else line = test;
    }
    lines.push(line);
    lines.slice(0,2).forEach((l,i)=> ctx.fillText(l.trim(), x, ly+i*lineHeight));
  }

  function drawFinal(){
    if(mode==='pfp') renderPFP();
    else {
      // Regenerate unique code each time badge is drawn
      uniqueCode = generateUniqueCode();
      renderBadge();
    }
  }

  // Title generation (same as before)
  const TITLE_POOLS = {
    frontend: ['Component Architect','Pixel-Precision Engineer','Interface Systems Lead','Render Loop Specialist'],
    backend: ['Query Optimization Lead','Systems Reliability Engineer','API Contract Specialist','Latency Reduction Unit'],
    ml: ['Gradient Descent Lead','Model Training Specialist','Inference Pipeline Engineer','Prompt Systems Architect'],
    ai: ['Model Training Specialist','Inference Pipeline Engineer','Prompt Systems Architect','Agent Orchestration Lead'],
    design: ['Systems Design Lead','Interface Craft Specialist','Design Ops Engineer','Visual Systems Architect'],
    infra: ['Infrastructure Lead','Deployment Systems Engineer','Reliability Specialist','Platform Architect'],
    devops: ['Deployment Systems Engineer','Pipeline Architect','Reliability Specialist','Platform Ops Lead'],
    product: ['Roadmap Systems Lead','Scope Architect','Product Ops Specialist','Priority Systems Engineer'],
    founder: ['Chief Everything Officer','Zero-to-One Specialist','Runway Systems Lead','Founding Engineer'],
    security: ['Threat Systems Lead','Vulnerability Research Engineer','Security Architect','Zero-Day Specialist'],
    mobile: ['Release Systems Engineer','Native Platform Architect','Build Pipeline Lead','App Systems Specialist'],
    generic: ['Full-Stack Engineer','Chief Bug Resolver','Ship-It Specialist','Merge Conflict Lead',
              'Systems Generalist','Build Systems Architect','Prototype Engineer','Debug Systems Lead',
              'Rapid Iteration Specialist','Deploy-First Engineer']
  };
  function pickTitle(role){
    const r = (role||'').toLowerCase();
    let pool = null;
    for(const key of ['frontend','backend','ml','ai','design','infra','devops','product','founder','security','mobile']){
      if(r.includes(key)) { pool = TITLE_POOLS[key]; break; }
    }
    if(!pool) pool = TITLE_POOLS.generic;
    return pool[Math.floor(Math.random()*pool.length)];
  }
  $('rerollBtn').addEventListener('click', ()=>{
    $('titleInput').value = pickTitle($('roleInput').value);
    drawFinal();
  });
  $('nameInput').addEventListener('input', drawFinal);
  $('roleInput').addEventListener('input', drawFinal);
  $('companyInput').addEventListener('input', drawFinal);
  $('titleInput').addEventListener('input', drawFinal);
  $('titleInput').value = pickTitle('');

  function captionFor(){
    return "Hacker House Goa 2026 🌴 #FrameInGoa";
  }
  function filenameFor(){ return mode==='pfp' ? 'hh-goa-2026-pfp.png' : 'hh-goa-2026-builder-pass.png'; }
  function canvasToBlob(){ return new Promise(resolve=> finalCanvas.toBlob(b=>resolve(b), 'image/png', 1)); }

  $('downloadBtn').addEventListener('click', async ()=>{
    const blob = await canvasToBlob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filenameFor();
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 4000);
  });

  // Preview Modal Handlers
  function openPreviewModal(){
    const modal = $('previewModal');
    const img = $('modalPreviewImg');
    if(modal && img && finalCanvas){
      img.src = finalCanvas.toDataURL('image/png');
      modal.classList.remove('hidden');
    }
  }

  function closePreviewModal(){
    const modal = $('previewModal');
    if(modal) modal.classList.add('hidden');
  }

  if($('previewBtn')) $('previewBtn').addEventListener('click', openPreviewModal);
  if($('closePreviewModalBtn')) $('closePreviewModalBtn').addEventListener('click', closePreviewModal);
  if($('modalCloseBtn')) $('modalCloseBtn').addEventListener('click', closePreviewModal);
  if($('previewModal')) {
    $('previewModal').addEventListener('click', (e)=>{
      if(e.target === $('previewModal')) closePreviewModal();
    });
  }

  if($('modalDownloadBtn')) {
    $('modalDownloadBtn').addEventListener('click', ()=>{
      closePreviewModal();
      if($('downloadBtn')) $('downloadBtn').click();
    });
  }

  if($('modalShareBtn')) {
    $('modalShareBtn').addEventListener('click', ()=>{
      closePreviewModal();
      if($('shareBtn')) $('shareBtn').click();
    });
  }

  // Uploads the graphic to the backend and returns a shareable page URL whose
  // OG meta tags (og:image, etc.) point at this exact generated image, so
  // link previews on X/WhatsApp/etc. show the real graphic, not a blank card.
  async function uploadForSharePage(blob, caption){
    const fd = new FormData();
    fd.append('image', blob, filenameFor());
    fd.append('caption', caption);
    const uploadUrl = BACKEND_URL ? BACKEND_URL.replace(/\/$/,'') + '/api/upload' : '/api/upload';
    const res = await fetch(uploadUrl, { method:'POST', body: fd });
    if(!res.ok) throw new Error('upload failed');
    const data = await res.json();
    return data.shareUrl; // e.g. https://your-backend/share/abc123
  }

  $('shareBtn').addEventListener('click', async ()=>{
    const blob = await canvasToBlob();
    const caption = captionFor();
    const file = new File([blob], filenameFor(), { type:'image/png' });

    // Preferred: share the actual image file directly with the caption — no link/OG needed.
    if(navigator.canShare && navigator.canShare({ files:[file] })){
      try{ await navigator.share({ files:[file], text: caption }); return; }
      catch(err){ /* user cancelled the native share sheet — fall through */ }
    }

    // Fallback: upload so the link preview (OG image) shows the real generated graphic.
    if(BACKEND_URL){
      try{
        showStatus('Preparing your shareable link…');
        const shareUrl = await uploadForSharePage(blob, caption);
        hideStatus();
        window.open('https://twitter.com/intent/tweet?text=' + encodeURIComponent(caption) + '&url=' + encodeURIComponent(shareUrl), '_blank');
        return;
      }catch(err){ showStatus('Could not prepare link preview — downloading instead.'); }
    }

    // Last resort (no backend configured, no native share): download + open X with caption only.
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href=url; a.download=filenameFor(); document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 4000);
    window.open('https://twitter.com/intent/tweet?text=' + encodeURIComponent(caption), '_blank');
    showStatus('Image downloaded — attach it to the tweet that just opened.');
  });

  syncCropCanvasSize();
  drawCrop();
  drawFinal();
  if(document.fonts && document.fonts.ready){ document.fonts.ready.then(drawFinal); }
(function(){
  const c = document.getElementById('cursorFx');
  const ctx = c.getContext('2d');
  function resize(){ c.width = innerWidth; c.height = innerHeight; }
  addEventListener('resize', resize); resize();

  let particles = [];
  addEventListener('mousemove', e=>{
    particles.push({ x:e.clientX, y:e.clientY, life:1, r: 3+Math.random()*5, drift: (Math.random()-0.5)*1.5 });
    if(particles.length > 40) particles.shift();
  });

  function loop(){
    ctx.clearRect(0,0,c.width,c.height);
    particles.forEach(p=>{
      p.y -= 0.6;
      p.x += p.drift;
      const r = p.r * p.life;

      ctx.beginPath();
      ctx.arc(p.x, p.y, r, 0, Math.PI*2);
      ctx.strokeStyle = `rgba(180,230,255,${p.life*0.6})`;
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.fillStyle = `rgba(180,230,255,${p.life*0.12})`;
      ctx.fill();

      ctx.beginPath();
      ctx.arc(p.x - r*0.3, p.y - r*0.3, r*0.25, 0, Math.PI*2);
      ctx.fillStyle = `rgba(255,255,255,${p.life*0.7})`;
      ctx.fill();

      p.life -= 0.025;
    });
    particles = particles.filter(p=>p.life>0);
    requestAnimationFrame(loop);
  }
  loop();
})();
})();